/**
 * enum of the possible interaction states for the radio buttons
 * @author John Blanco
 */
import '../../../globals.js';
import Enumeration from '../../../phet-core/js/Enumeration.js';
import EnumerationValue from '../../../phet-core/js/EnumerationValue.js';
import sun from '../sun.js';
class RadioButtonInteractionState extends EnumerationValue {
}
// the button is selected
RadioButtonInteractionState.SELECTED = new RadioButtonInteractionState();
// the button is deselected
RadioButtonInteractionState.DESELECTED = new RadioButtonInteractionState();
// a pointer is over the button, but it is not being pressed and is not selected
RadioButtonInteractionState.OVER = new RadioButtonInteractionState();
// the button is being pressed by the user
RadioButtonInteractionState.PRESSED = new RadioButtonInteractionState();
RadioButtonInteractionState.enumeration = new Enumeration(RadioButtonInteractionState);
export default RadioButtonInteractionState;
sun.register('RadioButtonInteractionState', RadioButtonInteractionState);
